<?php session_start(); require_once __DIR__.'/../config/database.php'; require_role('company'); $data=db_load(); $company=db_company_by_user($data,(int)$_SESSION['user_id']); $cid=(int)($company['id']??0); $message=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['internship_id']??0);$action=$_POST['action']??''; foreach($data['internships'] as &$i){if((int)$i['id']===$id&&(int)$i['company_id']===$cid){if($action==='toggle')$i['status']=$i['status']==='Open'?'Closed':'Open';}}unset($i);if(db_save($data))$message='Internship status updated.';} $rows=[];foreach($data['internships'] as $i)if((int)$i['company_id']===$cid){$i['applicant_count']=count(array_filter($data['applications'],fn($a)=>(int)$a['internship_id']===(int)$i['id']));$rows[]=$i;}db_sort_newest($rows);$flash=take_flash(); ?>
<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Internships · Arti Vaniyar Internships Hub</title><link rel="stylesheet" href="../css/style.css"></head><body><?php include 'company_nav.php'; ?><main class="dashboard"><div class="page-heading"><div><p class="eyebrow">ROLE MANAGEMENT</p><h1>My internships.</h1><p>Control which opportunities are currently accepting applications.</p></div><a class="btn primary" href="add_internship.php">Add new</a></div><?php if($flash): ?><div class="alert success"><?=e($flash['message'])?></div><?php endif; ?><?php if($message): ?><div class="alert success"><?=e($message)?></div><?php endif; ?><div class="table-card"><table><thead><tr><th>Role</th><th>Location</th><th>Applicants</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="5" class="empty">No internships posted yet.</td></tr><?php else: foreach($rows as $r): ?><tr><td><strong><?=e($r['title'])?></strong><br><small><?=e($r['duration']?:'Duration not set')?></small></td><td><?=e($r['location'])?></td><td><?=e($r['applicant_count'])?></td><td><span class="status <?=$r['status']==='Open'?'open':'rejected'?>"><?=e($r['status'])?></span></td><td><form method="POST"><input type="hidden" name="internship_id" value="<?=$r['id']?>"><input type="hidden" name="action" value="toggle"><button class="btn small" type="submit"><?=$r['status']==='Open'?'Close':'Reopen'?></button></form></td></tr><?php endforeach; endif; ?></tbody></table></div></main></body></html>
